item.content:encoded:
/*******************/
/* One off changes */

/* Change variation backorder date fonts */
.woocommerce-variation-backorder-date .estimate, span.variation-date, .woocommerce.single-product div.product form.cart p.stock.out-of-stock{
	color: #ff3333;
	font-weight: 700;
	font-size: 22px;
	text-transform: uppercase;
}

.woocommerce div.product form.cart .single_variation_wrap p.stock.available-on-backorder{
	margin-bottom: 0px;
}

/* Hiding shipping option traces */
tr.woocommerce-shipping-totals.shipping, #wc-local-pickup-plus-toggle-default-handling{
	display: none;
}

/* End one off changes */
/***********************/

.woocommerce-orders-table .woocommerce-orders-table__cell  .woocommerce-button{
	margin-right: 10px;
	margin-bottom: 5px;
	background-color: #a4243b;
}

.woocommerce-orders-table .woocommerce-orders-table__cell  .woocommerce-button:hover{
	background-color: #701929;
}

.shop_table.woocommerce-checkout-review-order-table th, 
.shop_table.woocommerce-checkout-review-order-table td {
	width: 50%;
}

.woocommerce-shipping-fields{
	display: none;
}

.woocommerce-page.woocommerce-checkout form .form-row:last-child, .woocommerce.woocommerce-checkout form .form-row:last-child {
    margin-bottom: 6px;
}

.woocommerce .single_add_to_cart_button.disabled{
	background-color: gray!important;
}

span.stock.in-stock{
	display: block;
	font-weight: 700;
	text-transform: uppercase;
	font-size: 22px;
}

.ast-stock-avail, p.stock.available-on-backorder{
	display: none;
}



/* WooCommerce Backorder Checkout */
.wc-item-meta{
	margin-bottom: 0;
}

.not-in-checkout{
	display: none;
}

.estimated-backorder-date{
	margin-left: 45px;
	font-size: 15px!important
}

/* END WooCommerce Backorder Checkout */



/* HIDE ESTIMATE IN CART */
.woocommerce-shipping-destination {
	display: none
}

.woocommerce-cart .pickup-location-address{
	margin-bottom: 0px;
}

.shipping-calculator-button {
	display: none
}

/* END HIDE */


/***********************/
/*   Pickup Location   */
.woocommerce-cart ul#shipping_method li {
    margin: 0;
    padding: .25em 0 .25em 0px;
    text-indent: 0px;
    list-style: none outside;
}

.woocommerce-cart .product-name .pickup-location-field.pickup-location-cart-item-field, 
.woocommerce-checkout .product-name .pickup-location-field.pickup-location-cart-item-field{
	display: none;
}

.woocommerce-shipping-contents small{
	display: none;
}

/* End Pickup Location */
/***********************/

/* First Login Page */
.first-login-page{
	background-color: #F5F5F5;
}

.first-login-container{
	max-width: 320px;
	background-color: white;
	margin: 50px auto;
	padding: 26px 24px 46px 24px;
	box-shadow: 0 0 10px #aaaaaa;
}

.first-login-page h1{
	font-size: 24px;
	color: #ec8a22;
	text-align: center;
	margin-bottom: 10px;
	font-weight: 700;
}

.first-login-page p{
	font-size: 14px;
	font-family: Arial, sans-serif;
	margin-bottom: 10px;
	line-height: 1.4em;
}

.first-login-page input{
	width: 100%;
	border-radius: 3px;
	margin-bottom: 10px;
}

.first-login-page .formbtn input{
	background-color: #A4243B;
	transition-duration: .333s;
}

.first-login-page .formbtn input:hover{
	background-color: #701929;
}



/* Account Page */

.woocommerce .woocommerce-MyAccount-content .button.mwb_wrma_wallet{
	display: none;
}

/* End Account Page */

.woocommerce .astra-shop-summary-wrap a.add_to_cart_button{
	background-color: #A4243B;
	transition-duration: .333s;
}

.woocommerce .astra-shop-summary-wrap a.add_to_cart_button:hover{
	background-color: #701929;
}

.woocommerce-NoticeGroup.woocommerce-NoticeGroup-checkout .woocommerce-error,
.woocommerce-NoticeGroup.woocommerce-NoticeGroup-checkout .woocommerce-error:before{
	font-size: 18px!important;
	background-color: #B81C23;
	color: white!important;
}

/* Hide account balance deposit form */
.ywf_make_a_deposit_form,
.woocommerce-MyAccount-navigation-link--make-a-deposit {
	display: none;
}


/* Checkout order detail width*/
.post-39 .woocommerce-checkout-review-order tfoot .shipping.pickup_location td {
	max-width: 200px;
}
@media (min-width: 1140px) {.post-39 .woocommerce-checkout-review-order tfoot .shipping.pickup_location td {
	max-width: 300px;
}
}

.toggle-default-handling.ship {
	display: none;
}

.post-39 .woocommerce-checkout-review-order tfoot .shipping.pickup_location th {
	visibility: hidden;
}
.post-39 .woocommerce-checkout-review-order tfoot .shipping.pickup_location th:before {
	content: "Pickup Location";
	visibility: visible;
}

